--- docs/billing.md
# Billing

Prices live in the payment provider. Never create them in code or by hand in the provider dashboard:
edit config/plans.json and run node scripts/sync-plans.js, which keeps the provider and this file in step.

--- scripts/sync-plans.js
// Reads config/plans.json and creates or updates the matching prices in the payment provider.
const { plans } = require('../config/plans.json');

function diff(remote) {
  const have = new Set(remote.map((p) => p.id));
  return plans.filter((p) => !have.has(p.provider_price)).map((p) => ({ create: p.provider_price, amount: p.amount_cents, interval: p.interval }));
}

if (require.main === module) console.log(JSON.stringify(diff([]), null, 2));

module.exports = { diff };

--- test/changes.test.js
const test = require('node:test');
const assert = require('node:assert');
const { changePlan } = require('../src/changes');

test('a plan change waits for the end of the period', () => {
  const sub = { id: 's1', plan_id: 'team_monthly', period_end: '2026-11-30T00:00:00Z' };
  const next = changePlan(sub, { id: 'business_monthly' });
  assert.strictEqual(next.plan_id, 'team_monthly');
  assert.strictEqual(next.effective_at, sub.period_end);
});

--- test/revrec.test.js
// Finance recognises revenue month by month, and the month-end close reads these schedules.
const test = require('node:test');
const assert = require('node:assert');
const { schedule } = require('../src/revrec');

test('a monthly invoice is recognised in its month', () => {
  assert.deepStrictEqual(schedule({ period_start: '2026-10-01', amount_cents: 4900 }), [{ month: '2026-10', amount_cents: 4900 }]);
});

